def calculate_a(n):
    if n == 1:
        return 0
    memo = {}
    def recursive_a(k):
        if k in memo:
            return memo[k]
        if k == 1:
            return 0

        floor_k_div_2 = k // 2
        ceil_k_div_2 = (k + 1) // 2

        # a_n = a_{floor(n/2)} + a_{ceil(n/2)} + floor(n/2)
        result = recursive_a(floor_k_div_2) + recursive_a(ceil_k_div_2) + floor_k_div_2
        memo[k] = result
        return result

    return recursive_a(n)

N = 2025
a_2025 = calculate_a(N)
print(f"a_{N} = {a_2025}")
